package nl.bandit.warps.menu;
import nl.bandit.warps.*; import nl.bandit.warps.model.Warp; import org.bukkit.*; import org.bukkit.configuration.*; import org.bukkit.configuration.file.*; import org.bukkit.entity.Player; import org.bukkit.inventory.*; import org.bukkit.inventory.meta.ItemMeta; import java.io.*; import java.util.*;
public final class MenuService {
 private final BanditWarpsPlugin plugin; private YamlConfiguration menus,icons; private final Map<UUID,Warp> editing=new HashMap<>();private final Map<UUID,Integer> sort=new HashMap<>();
 public MenuService(BanditWarpsPlugin p){plugin=p;reload();}public void reload(){menus=YamlConfiguration.loadConfiguration(new File(plugin.getDataFolder(),"menus.yml"));icons=YamlConfiguration.loadConfiguration(new File(plugin.getDataFolder(),"icons.yml"));}
 private String color(String s){return s.replace('&','§');}private String vars(String s,Warp w){return color(s.replace("%warp_name%",w.name).replace("%warp_description%",w.description.isBlank()?"Geen beschrijving":w.description).replace("%warp_visitors%",""+w.visitors).replace("%warp_icon%",w.icon).replace("%warp_status%",w.isPublic?"&aOpenbaar":"&cPrivé"));}
 private ItemStack item(ConfigurationSection s,Warp w){Material mat=Material.matchMaterial(s.getString("material","BARRIER"));ItemStack i=new ItemStack(mat==null?Material.BARRIER:mat);ItemMeta m=i.getItemMeta();m.setDisplayName(vars(s.getString("name"," "),w));List<String> lore=new ArrayList<>();for(String x:s.getStringList("lore"))lore.add(vars(x,w));m.setLore(lore);i.setItemMeta(m);return i;}
 private Inventory base(String key){int size=menus.getInt(key+".rows",6)*9;Inventory i=Bukkit.createInventory(null,size,color(menus.getString(key+".title")));if(menus.getBoolean(key+".border.enabled",true)){ItemStack b=item(menus.getConfigurationSection(key+".border.item"),new Warp("x",new UUID(0,0)," ",null));for(int x=0;x<size;x++)if(x<9||x>=size-9||x%9==0||x%9==8)i.setItem(x,b);}return i;}
 public void settings(Player p,Warp w){editing.put(p.getUniqueId(),w);Inventory i=base("settings");for(String k:List.of("status","description","icon","confirm")){ConfigurationSection c=menus.getConfigurationSection("settings.items."+k);i.setItem(c.getInt("slot"),item(c,w));}p.openInventory(i);}
 public void icons(Player p,Warp w){Inventory i=base("icons");int slot=menus.getInt("icons.start-slot",10);for(String id:icons.getConfigurationSection("icons").getKeys(false))if(p.hasPermission("banditwarps.icon."+id)){i.setItem(slot++,item(icons.getConfigurationSection("icons."+id),w));}p.openInventory(i);}
 public void browser(Player p){Inventory i=base("browser");List<Warp> ws=new ArrayList<>();for(Warp w:plugin.warps().all())if(w.isPublic||w.owner.equals(p.getUniqueId()))ws.add(w);int mode=sort.getOrDefault(p.getUniqueId(),0);if(mode==0)ws.sort(Comparator.comparingInt((Warp w)->w.visitors).reversed());if(mode==1)Collections.shuffle(ws);int slot=10;for(Warp w:ws){if(slot>=45)break;i.setItem(slot++,item(icons.getConfigurationSection("icons."+w.icon),w));}Warp dummy=new Warp("x",p.getUniqueId(),"x",p.getLocation());ConfigurationSection so=menus.getConfigurationSection("browser.items.sort");ItemStack si=item(so,dummy);ItemMeta sm=si.getItemMeta();sm.setDisplayName(color("&eSorteren: &f"+List.of("MEESTE BEZOEKERS","RANDOM")[mode]));si.setItemMeta(sm);i.setItem(so.getInt("slot"),si);ConfigurationSection ow=menus.getConfigurationSection("browser.items.your-warps");i.setItem(ow.getInt("slot"),item(ow,dummy));p.openInventory(i);}
 public void owned(Player p){Inventory i=base("owned");int slot=10;for(Warp w:plugin.warps().all())if(w.owner.equals(p.getUniqueId())&&slot<45)i.setItem(slot++,item(icons.getConfigurationSection("icons."+w.icon),w));p.openInventory(i);}public Warp editing(Player p){return editing.get(p.getUniqueId());}public void nextSort(Player p){sort.put(p.getUniqueId(),1-sort.getOrDefault(p.getUniqueId(),0));}public String icon(ItemStack i){for(String id:icons.getConfigurationSection("icons").getKeys(false))if(icons.getString("icons."+id+".material").equals(i.getType().name()))return id;return null;}
}
